'use client';

import * as React from 'react';
import { cn } from '@/lib/utils';

export interface RadioProps extends Omit<React.InputHTMLAttributes<HTMLInputElement>, 'type' | 'onChange'> {
  /** Controlled checked state; omit for uncontrolled usage. */
  checked?: boolean;
  /** Fired when the user selects this radio. */
  onCheckedChange?: (checked: boolean) => void;
}

/**
 * Accessible radio built on the native input, to be used inside a
 * `RadioGroup` (which provides the shared `name`). Platform keyboard
 * navigation and form semantics come for free.
 */
const Radio = React.forwardRef<HTMLInputElement, RadioProps>(
  ({ className, checked, onCheckedChange, ...props }, ref) => (
    <input
      type="radio"
      ref={ref}
      checked={checked}
      onChange={(event) => onCheckedChange?.(event.target.checked)}
      className={cn(
        'h-4 w-4 shrink-0 rounded-full border border-primary',
        'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background',
        'disabled:cursor-not-allowed disabled:opacity-50',
        'checked:bg-primary checked:text-primary-foreground',
        className
      )}
      {...props}
    />
  )
);
Radio.displayName = 'Radio';

export interface RadioGroupProps {
  /** Shared name applied to every radio in the group. */
  name: string;
  /** Accessible group label; rendered as <legend> inside a fieldset. */
  legend?: string;
  /** Currently selected value (controlled). */
  value?: string;
  /** Initial value (uncontrolled). */
  defaultValue?: string;
  /** Called with the newly selected value. */
  onValueChange?: (value: string) => void;
  className?: string;
  children: React.ReactNode;
}

/**
 * Groups related radios with a shared name and accessible legend.
 * Renders a native <fieldset>/<legend> so screen readers announce the
 * group context alongside each option.
 */
const RadioGroup = React.forwardRef<HTMLFieldSetElement, RadioGroupProps>(
  ({ name, legend, value, defaultValue, onValueChange, className, children }, ref) => {
    const [internalValue, setInternalValue] = React.useState(defaultValue ?? '');
    const currentValue = value ?? internalValue;

    const handleChange = (next: string) => {
      if (value === undefined) setInternalValue(next);
      onValueChange?.(next);
    };

    return (
      <fieldset ref={ref} className={cn('space-y-2', className)}>
        {legend && <legend className="text-sm font-medium">{legend}</legend>}
        <RadioGroupContext.Provider value={{ name, value: currentValue, onChange: handleChange }}>
          {children}
        </RadioGroupContext.Provider>
      </fieldset>
    );
  }
);
RadioGroup.displayName = 'RadioGroup';

type RadioGroupContextValue = {
  name: string;
  value: string;
  onChange: (value: string) => void;
};

const RadioGroupContext = React.createContext<RadioGroupContextValue>({
  name: '',
  value: '',
  onChange: () => {},
});

export interface RadioGroupItemProps extends Omit<RadioProps, 'name' | 'checked' | 'onCheckedChange' | 'value'> {
  /** The value this item contributes to the group. */
  value: string;
  /** Visible label rendered next to the radio. */
  label?: string;
}

/** A single radio option inside a `RadioGroup`. */
const RadioGroupItem = React.forwardRef<HTMLInputElement, RadioGroupItemProps>(
  ({ value, label, className, id, ...props }, ref) => {
    const group = React.useContext(RadioGroupContext);
    const generatedId = React.useId();
    const inputId = id ?? generatedId;

    return (
      <div className="flex items-center gap-2">
        <Radio
          ref={ref}
          id={inputId}
          name={group.name}
          value={value}
          checked={group.value === value}
          onCheckedChange={(checked) => checked && group.onChange(value)}
          className={className}
          {...props}
        />
        {label && (
          <label htmlFor={inputId} className="text-sm leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70">
            {label}
          </label>
        )}
      </div>
    );
  }
);
RadioGroupItem.displayName = 'RadioGroupItem';

export { Radio, RadioGroup, RadioGroupItem };

{
  "id": "radio",
  "name": "Radio",
  "tier": "atom",
  "description": "Native radio buttons grouped for mutually exclusive choices, with an accessible fieldset/legend wrapper",
  "designIntent": "Radio lets users pick exactly one option from a visible set. RadioGroup provides the shared name and accessible legend so screen readers announce group context.",
  "props": [
    {
      "name": "value",
      "type": "string",
      "required": true,
      "description": "The value this item contributes to the group"
    },
    {
      "name": "label",
      "type": "string",
      "required": false,
      "description": "Visible label rendered next to the radio"
    },
    {
      "name": "checked",
      "type": "boolean",
      "required": false,
      "description": "Controlled checked state (on Radio)"
    },
    {
      "name": "onCheckedChange",
      "type": "(checked: boolean) => void",
      "required": false,
      "description": "Fired when the user selects this radio (on Radio)"
    },
    {
      "name": "disabled",
      "type": "boolean",
      "defaultValue": "false",
      "required": false,
      "description": "Disables the radio"
    },
    {
      "name": "legend",
      "required": false,
      "type": "string",
      "description": "Accessible group label; rendered as <legend> inside a fieldset (RadioGroup component)"
    },
    {
      "name": "onValueChange",
      "required": false,
      "type": "(value: string) => void",
      "description": "Called with the newly selected value (RadioGroup component)"
    },
    {
      "name": "defaultValue",
      "required": false,
      "type": "string",
      "description": "Initial selected value when uncontrolled (RadioGroup component)"
    }
  ],
  "examples": [
    {
      "title": "Radio group",
      "code": "<RadioGroup name=\"plan\" legend=\"Choose a plan\" defaultValue=\"free\">\n  <RadioGroupItem value=\"free\" label=\"Free\" />\n  <RadioGroupItem value=\"pro\" label=\"Pro\" />\n</RadioGroup>",
      "description": "Mutually exclusive plan selection"
    },
    {
      "title": "Controlled group",
      "code": "<RadioGroup\n  name=\"plan\"\n  legend=\"Plan\"\n  value={plan}\n  onValueChange={setPlan}\n>\n  <RadioGroupItem value=\"free\" label=\"Free\" />\n  <RadioGroupItem value=\"pro\" label=\"Pro\" />\n</RadioGroup>",
      "description": "Group driven by parent state"
    }
  ],
  "antiPatterns": [
    {
      "title": "Don't use Radio for multi-select",
      "explanation": "Radio is single-choice. Use Checkbox when users can pick more than one option.",
      "example": "// Avoid: Radios for multi-select\n<RadioGroup name=\"tags\">...</RadioGroup>\n\n// Prefer: Checkboxes\n<Checkbox /> React\n<Checkbox /> TypeScript"
    },
    {
      "title": "Don't render bare radios without a group",
      "explanation": "Without RadioGroup there is no shared name or legend, so screen readers can't convey the grouping.",
      "example": "// Avoid\n<Radio name=\"x\" value=\"a\" />\n\n// Prefer\n<RadioGroup name=\"x\" legend=\"Options\">\n  <RadioGroupItem value=\"a\" label=\"A\" />\n</RadioGroup>"
    }
  ],
  "accessibility": [
    {
      "feature": "Group semantics",
      "implementation": "RadioGroup renders a fieldset with a legend so the group name is announced",
      "userRequirements": "Always provide a legend describing the choice"
    },
    {
      "feature": "Arrow-key navigation",
      "implementation": "Native radio behavior: arrows move selection within the group",
      "userRequirements": "Don't override keyboard handlers"
    }
  ],
  "contentGuidelines": [
    {
      "contentType": "Labels",
      "guidelines": [
        "Make options mutually exclusive and collectively exhaustive",
        "Use parallel phrasing across options",
        "Include an Other/free-text option when the set can't be closed"
      ],
      "goodExamples": [
        "Free",
        "Pro",
        "Enterprise"
      ],
      "badExamples": [
        "Option 1",
        "Yes (pick this)",
        "Free plan for now"
      ]
    }
  ],
  "compositionRules": [
    {
      "component": "RadioGroup",
      "relationship": "Always wrap Radio/RadioGroupItem in a RadioGroup",
      "example": "<RadioGroup name=\"x\" legend=\"Choose\"><RadioGroupItem value=\"a\" label=\"A\" /></RadioGroup>"
    }
  ],
  "relatedComponents": [
    "Checkbox",
    "Select",
    "Label"
  ],
  "package": "@slipstream-ui/core",
  "importPath": "@slipstream-ui/core",
  "version": "0.1.0",
  "sourceDir": "radio",
  "exportName": "Radio"
}
